import { Plugin, StringLiteralShape } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

describe('Shape Transforms', () => {
    test('toSubclass() cannot return an instance of the same class', async () => {
        const errors: unknown[][] = []
        const project = new Project({ logger: { ...console, error: (...args) => errors.push(args) } })

        project.getPlugins().prepend(
            Plugin.create({
                name: 'TestPlugin',
                shapes: [
                    {
                        shape: StringLiteralShape,
                        toSubclass(string) {
                            return {
                                success: true,
                                value: new StringLiteralShape({
                                    source: string,
                                    literalText: 'test',
                                }),
                            }
                        },
                    },
                ],
            })
        )

        const file = project.addFile({ path: 'src/fluent/test.now.ts', content: 'export const test = "test"' })
        await file.getOutput()

        expect(errors).toHaveLength(1)
        const [fullError] = errors
        expect(fullError).toBeDefined()
        expect(fullError).toHaveLength(2)

        const [parentMessage, pluginError] = fullError
        expect(typeof parentMessage).toBe('string')
        expect(pluginError).toBeInstanceOf(Error)
        expect((pluginError as Error).message).toBe(
            'Result of subclassing "StringLiteralShape" is an instance of the same class. The result MUST be a subclass.'
        )
    })
})
